## 1. Initialize session and CSRF protection

Add this to your existing application setup; reuse your existing `db` rather than creating a second database instance.

```python
# app/__init__.py
import os
from datetime import timedelta

from flask import Flask, jsonify
from flask_login import LoginManager
from flask_wtf.csrf import CSRFProtect, CSRFError

login_manager = LoginManager()
csrf = CSRFProtect()


def create_app():
    app = Flask(__name__)

    app.config.update(
        SECRET_KEY=os.environ["SECRET_KEY"],
        SESSION_COOKIE_HTTPONLY=True,
        SESSION_COOKIE_SAMESITE="Lax",
        # Enable for HTTPS deployments; disable only for local HTTP.
        SESSION_COOKIE_SECURE=os.environ.get("COOKIE_SECURE", "1") == "1",
        PERMANENT_SESSION_LIFETIME=timedelta(minutes=30),
    )

    # Keep your existing database and migration initialization here.
    login_manager.init_app(app)
    csrf.init_app(app)

    @login_manager.unauthorized_handler
    def unauthorized():
        return jsonify(error="Authentication required"), 401

    @app.errorhandler(CSRFError)
    def csrf_error(error):
        return jsonify(error="Invalid or missing CSRF token"), 400

    from app.auth.routes import auth
    app.register_blueprint(auth)

    return app
```

Use a strong, persistent secret from your deployment environment—not the literal `'secret_key'` or a fallback default.

